     8→function linearRegression(ys: number[]): { slope: number; intercept: number } {
     9→  const n = ys.length;
    10→  const xs = ys.map((_, i) => i);
    11→  const sumX = xs.reduce((a, b) => a + b, 0);
    12→  const sumY = ys.reduce((a, b) => a + b, 0);
    13→  const sumXY = xs.reduce((acc, x, i) => acc + x * ys[i], 0);
    14→  const sumX2 = xs.reduce((acc, x) => acc + x * x, 0);
    15→  const denom = n * sumX2 - sumX * sumX;
    16→  if (denom === 0) return { slope: 0, intercept: sumY / n };
    17→  const slope = (n * sumXY - sumX * sumY) / denom;
    18→  const intercept = (sumY - slope * sumX) / n;
    19→  return { slope, intercept };
    20→}
