   216→// ─── Status Stepper ───────────────────────────────────────────────────────────
   217→function StatusStepper({
   218→  status,
   219→  onAdvance,
   220→}: {
   221→  status: DeliveryStatus;
   222→  onAdvance: () => void;
   223→}) {
   224→  const { t } = useTranslation();
   225→
   226→  const steps: { key: DeliveryStatus; label: string; icon: React.ReactNode }[] = [
   227→    { key: "picked_up", label: t("driver.statusPickedUp"),  icon: <Box className="w-3 h-3" /> },
   228→    { key: "arrived",   label: t("driver.statusArrived"),   icon: <LocateFixed className="w-3 h-3" /> },
   229→    { key: "delivered", label: t("driver.statusDelivered"), icon: <BadgeCheck className="w-3 h-3" /> },
   230→  ];
   231→
   232→  const currentIdx = STEPS.indexOf(status);
   233→  const next = nextStep(status);
   234→
   235→  const nextLabels: Record<DeliveryStatus, string> = {
   236→    picked_up: t("driver.advanceToArrived"),
