   238→    delivered: "",
   239→  };
   240→
   241→  return (
   242→    <div className="flex flex-col gap-3">
   243→      {/* Step nodes */}
   244→      <div className="flex items-center gap-1">
   245→        {steps.map((step, i) => {
   246→          const done    = i <= currentIdx;
   247→          const current = i === currentIdx;
   248→          return (
   249→            <div key={step.key} className="flex items-center flex-1 last:flex-none">
   250→              {/* Node */}
   251→              <div className="flex flex-col items-center gap-1 shrink-0">
   252→                <motion.div
   253→                  animate={
   254→                    current
   255→                      ? { scale: [1, 1.1, 1], boxShadow: ["0 0 0px rgba(59,130,246,0)", "0 0 14px rgba(59,130,246,0.7)", "0 0 8px rgba(59,130,246,0.4)"] }
   256→                      : {}
   257→                  }
   258→                  transition={{ repeat: current ? Infinity : 0, duration: 2, ease: "easeInOut" }}
   259→                  className="w-7 h-7 rounded-xl flex items-center justify-center transition-all"
   260→                  style={{
   261→                    background: done
   262→                      ? current
   263→                        ? "linear-gradient(135deg,#1D4ED8,#3B82F6)"
   264→                        : "rgba(16,185,129,0.25)"
   265→                      : "rgba(255,255,255,0.06)",
   266→                    border: done
   267→                      ? current
