   280→                  style={{
   281→                    color: done
   282→                      ? current ? "rgba(147,197,253,0.95)" : "rgba(110,231,183,0.75)"
   283→                      : "rgba(255,255,255,0.2)",
   284→                  }}
   285→                >
   286→                  {step.label}
   287→                </span>
   288→              </div>
   289→
   290→              {/* Connector */}
   291→              {i < steps.length - 1 && (
   292→                <div className="flex-1 mx-1 mb-4 h-0.5 relative overflow-hidden rounded-full"
   293→                  style={{ background: "rgba(255,255,255,0.08)" }}>
   294→                  <motion.div
   295→                    className="h-full rounded-full"
   296→                    initial={{ width: 0 }}
   297→                    animate={{ width: i < currentIdx ? "100%" : "0%" }}
   298→                    transition={{ duration: 0.5, ease: "easeOut" }}
   299→                    style={{ background: "linear-gradient(90deg,rgba(16,185,129,0.6),rgba(59,130,246,0.5))" }}
   300→                  />
   301→                </div>
   302→              )}
   303→            </div>
   304→          );
   305→        })}
   306→      </div>
   307→
   308→      {/* Advance button */}
   309→      {next && (
   310→        <motion.button
   311→          whileTap={{ scale: 0.97 }}
   312→          whileHover={{ scale: 1.01 }}
