import { useEffect, useRef, useState, useCallback } from "react";
import { useTranslation } from "react-i18next";
import { motion, AnimatePresence } from "framer-motion";
import { Navigation, MapPin } from "lucide-react";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

// ─── Province Coordinates (Iraq / Kurdistan) ──────────────────────────────────
const PROVINCE_COORDS: Record<string, [number, number]> = {
  erbil:        [36.1901, 44.0091],
  sulaymaniyah: [35.5568, 45.4351],
  duhok:        [36.8678, 42.9887],
  halabja:      [35.1780, 45.9864],
  kirkuk:       [35.4681, 44.3922],
  baghdad:      [33.3152, 44.3661],
  basra:        [30.5085, 47.7804],
  mosul:        [36.3438, 43.1158],
  najaf:        [31.9971, 44.3351],
  karbala:      [32.6169, 44.0244],
  anbar:        [33.4298, 43.2963],
  diyala:       [33.7651, 44.6188],
};

function haversineKm(a: [number, number], b: [number, number]): number {
  const R = 6371;
  const dLat = ((b[0] - a[0]) * Math.PI) / 180;
  const dLon = ((b[1] - a[1]) * Math.PI) / 180;
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((a[0] * Math.PI) / 180) *
      Math.cos((b[0] * Math.PI) / 180) *
      Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
}

// ─── Custom SVG Icons ─────────────────────────────────────────────────────────
function makePinIcon(color: string, letter: string): L.DivIcon {
  const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="30" height="38" viewBox="0 0 30 38">
      <ellipse cx="15" cy="36" rx="5" ry="1.8" fill="rgba(0,0,0,0.3)"/>
      <path d="M15 1C8.9 1 4 5.9 4 12c0 7 11 25 11 25S26 19 26 12C26 5.9 21.1 1 15 1z" fill="${color}" stroke="white" stroke-width="1.5"/>
      <circle cx="15" cy="12" r="5.5" fill="white"/>
      <text x="15" y="15.5" text-anchor="middle" font-size="7" font-weight="900" font-family="system-ui,sans-serif" fill="${color}">${letter}</text>
    </svg>`;
  return L.divIcon({
    html: svg,
    className: "",
    iconSize: [30, 38],
    iconAnchor: [15, 38],
    popupAnchor: [0, -40],
  });
}

function makeTruckIcon(): L.DivIcon {
  const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="38" height="38" viewBox="0 0 38 38">
      <circle cx="19" cy="19" r="17" fill="rgba(251,191,36,0.95)" stroke="rgba(255,255,255,0.9)" stroke-width="2.5"/>
      <text x="19" y="25" text-anchor="middle" font-size="18">🚚</text>
    </svg>`;
  return L.divIcon({
    html: svg,
    className: "",
    iconSize: [38, 38],
    iconAnchor: [19, 19],
  });
}

// ─── Route helpers ────────────────────────────────────────────────────────────
const ROUTE_STEPS = 70;

function buildRoute(
  pickup: [number, number],
  delivery: [number, number]
): [number, number][] {
  return Array.from({ length: ROUTE_STEPS + 1 }, (_, i) => {
    const f = i / ROUTE_STEPS;
    // add a gentle arc via a midpoint offset for visual interest
    const arc = Math.sin(f * Math.PI) * 0.18;
    const midLat = (pickup[0] + delivery[0]) / 2 + arc * (delivery[1] - pickup[1]);
    const midLng = (pickup[1] + delivery[1]) / 2 - arc * (delivery[0] - pickup[0]);
    const lat = (1 - f) * (1 - f) * pickup[0] + 2 * (1 - f) * f * midLat + f * f * delivery[0];
    const lng = (1 - f) * (1 - f) * pickup[1] + 2 * (1 - f) * f * midLng + f * f * delivery[1];
    return [lat, lng] as [number, number];
  });
}

// ─── Component ────────────────────────────────────────────────────────────────
interface DeliveryMapProps {
  pickupProvince: string;
  deliveryProvince: string;
  status: string;
  onArrived: () => void;
}

export function DeliveryMap({
  pickupProvince,
  deliveryProvince,
  status,
  onArrived,
}: DeliveryMapProps) {
  const { t } = useTranslation();

  const containerRef   = useRef<HTMLDivElement>(null);
  const mapRef         = useRef<L.Map | null>(null);
  const driverRef      = useRef<L.Marker | null>(null);
  const animRef        = useRef<ReturnType<typeof setInterval> | null>(null);
  const initializedRef = useRef(false);

  const [showMap,        setShowMap]        = useState(false);
  const [isNavigating,   setIsNavigating]   = useState(false);
  const [navDone,        setNavDone]        = useState(false);
  const [progress,       setProgress]       = useState(0);
  const [showArrival,    setShowArrival]    = useState(false);

  const pickup   = PROVINCE_COORDS[pickupProvince]   ?? [36.19, 44.01];
  const delivery = PROVINCE_COORDS[deliveryProvince] ?? [33.32, 44.37];
  const route    = buildRoute(pickup, delivery);

  const distKm  = Math.round(haversineKm(pickup, delivery));
  const etaMins = Math.max(1, Math.round(distKm * 1.3)); // ~1.3 min/km driving

  const remKm   = Math.round(distKm  * (1 - progress));
  const remMins = Math.max(0, Math.round(etaMins * (1 - progress)));

  // ── Map init ────────────────────────────────────────────────────────────────
  const initMap = useCallback(() => {
    if (initializedRef.current || !containerRef.current) return;
    initializedRef.current = true;

    const map = L.map(containerRef.current, {
      zoomControl: true,
      attributionControl: false,
      scrollWheelZoom: true,
    });

    L.tileLayer("https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png", {
      subdomains: "abcd",
      maxZoom: 19,
    }).addTo(map);

    const bounds = L.latLngBounds([pickup, delivery]);
    map.fitBounds(bounds, { padding: [50, 50] });

    L.marker(pickup, { icon: makePinIcon("#3B82F6", "A") })
      .addTo(map)
      .bindPopup(`<b style="font-family:system-ui">${t("driver.map.pickupPoint")}</b>`);

    L.marker(delivery, { icon: makePinIcon("#10B981", "B") })
      .addTo(map)
      .bindPopup(`<b style="font-family:system-ui">${t("driver.map.deliveryPoint")}</b>`);

    L.polyline(route, {
      color: "rgba(59,130,246,0.55)",
      weight: 4,
      dashArray: "9 7",
      lineCap: "round",
    }).addTo(map);

    const driver = L.marker(pickup, { icon: makeTruckIcon(), zIndexOffset: 1000 }).addTo(map);
    driverRef.current = driver;
    mapRef.current    = map;
  }, [pickup, delivery, route, t]);

  useEffect(() => {
    if (!showMap) return;
    const timer = setTimeout(() => {
      initMap();
      mapRef.current?.invalidateSize();
    }, 120);
    return () => clearTimeout(timer);
  }, [showMap, initMap]);

  useEffect(() => {
    return () => {
      if (animRef.current) clearInterval(animRef.current);
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current    = null;
        initializedRef.current = false;
      }
    };
  }, []);

  // ── Navigation simulation ────────────────────────────────────────────────────
  const startNav = () => {
    if (!mapRef.current || isNavigating || navDone) return;
    setIsNavigating(true);

    let step = 0;
    animRef.current = setInterval(() => {
      step++;
      const frac = step / ROUTE_STEPS;
      setProgress(frac);

      const pos = route[Math.min(step, ROUTE_STEPS)];
      driverRef.current?.setLatLng(pos);
      mapRef.current?.panTo(pos, { animate: true, duration: 0.3 });

      if (step >= ROUTE_STEPS) {
        clearInterval(animRef.current!);
        animRef.current = null;
        setIsNavigating(false);
        setNavDone(true);
        setShowArrival(true);
        setTimeout(() => {
          setShowArrival(false);
          onArrived();
        }, 2800);
      }
    }, 200);
  };

  const canNavigate = status === "picked_up" && !navDone;

  return (
    <div className="flex flex-col gap-2">
      {/* ── Show/Hide toggle ──────────────────────────────────────────────────── */}
      <button
        onClick={() => setShowMap((v) => !v)}
        className="self-start flex items-center gap-1.5 text-[10px] font-bold px-2.5 py-1.5 rounded-lg transition-all"
        style={{
          background: showMap
