// ─── Tab components ───────────────────────────────────────────────────────────
type Tab = "overview" | "kyc" | "badges";

// ─── Main Component ───────────────────────────────────────────────────────────
export default function AdminCentral() {
  const { t } = useTranslation();

  const [activeTab, setActiveTab] = useState<Tab>("overview");
  const [suppliers, setSuppliers] = useState<Supplier[]>(DEMO_SUPPLIERS);
  const [filterStatus, setFilterStatus] = useState<"all" | SupplierStatus>("all");
  const [badgeTarget, setBadgeTarget] = useState<Supplier | null>(null);
  const [toast, setToast] = useState<{ msg: string; type: "success" | "error" } | null>(null);

  const showToast = (msg: string, type: "success" | "error" = "success") => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleApprove = (id: string) => {
    const s = suppliers.find((x) => x.id === id);
    if (s) setBadgeTarget(s);
  };

  const handleReject = (id: string) => {
    setSuppliers((prev) =>
      prev.map((s) => (s.id === id ? { ...s, status: "rejected" as const } : s))
    );
    showToast(t("admin.rejectSuccess"), "error");
  };

  const handleAssignBadge = (badge: TrustBadge) => {
    if (!badgeTarget) return;
    setSuppliers((prev) =>
      prev.map((s) =>
        s.id === badgeTarget.id ? { ...s, status: "approved" as const, badge } : s
      )
    );
    setBadgeTarget(null);
    showToast(t("admin.approveSuccess"));
  };

  const filtered = useMemo(() => {
    if (filterStatus === "all") return suppliers;
    return suppliers.filter((s) => s.status === filterStatus);
  }, [suppliers, filterStatus]);

  const pendingCount   = suppliers.filter((s) => s.status === "pending").length;
  const approvedCount  = suppliers.filter((s) => s.status === "approved").length;
  const badgeBreakdown = (Object.keys(BADGE_CONFIG) as TrustBadge[]).map((b) => ({
    badge: b,
