          <div className="flex items-center gap-3 mb-1.5">
            <div className="w-10 h-10 rounded-2xl flex items-center justify-center shrink-0"
              style={{
                background: "linear-gradient(135deg,rgba(29,78,216,0.4),rgba(59,130,246,0.25))",
