                      <div className="absolute -top-4 -end-4 w-14 h-14 rounded-full opacity-20"
                        style={{ background: cfg.color, filter: "blur(10px)" }} />
                      <div className="w-12 h-12 rounded-2xl flex items-center justify-center"
                        style={{ background: cfg.bg, border: `1.5px solid ${cfg.border}`, boxShadow: `0 0 16px ${cfg.glow}` }}>
                        <Icon className="w-6 h-6" style={{ color: cfg.color }} />
                      </div>
                      <div>
                        <p className="text-2xl font-extrabold" style={{ color: cfg.color }}>{count}</p>
                        <p className="text-[10px] font-bold mt-0.5" style={{ color: "rgba(255,255,255,0.55)" }}>
                          {t(cfg.labelKey)}
                        </p>
                      </div>
                    </motion.div>
                  );
                })}
              </div>

              {/* Suppliers with badges */}
              <div className="rounded-2xl overflow-hidden"
                style={{ background: "rgba(255,255,255,0.025)", border: "1px solid rgba(255,255,255,0.07)" }}>
                <div className="px-5 py-3.5 flex items-center gap-2"
                  style={{ borderBottom: "1px solid rgba(255,255,255,0.06)" }}>
                  <Award className="w-4 h-4" style={{ color: "rgba(251,191,36,0.8)" }} />
                  <h3 className="text-white font-extrabold text-sm">{t("admin.badgedSuppliers")}</h3>
                </div>
                <div className="divide-y" style={{ borderColor: "rgba(255,255,255,0.04)" }}>
                  {suppliers.filter((s) => s.badge).length === 0 ? (
                    <div className="px-5 py-8 text-center">
                      <p className="text-white/30 text-sm">{t("admin.noBadgesYet")}</p>
                    </div>
                  ) : (
                    suppliers.filter((s) => s.badge).map((s, i) => (
                      <motion.div key={s.id}
                        initial={{ opacity: 0 }} animate={{ opacity: 1 }}
                        transition={{ delay: i * 0.05 }}
                        className="px-5 py-3 flex items-center gap-3">
                        <div className="w-8 h-8 rounded-xl flex items-center justify-center shrink-0"
                          style={{ background: "rgba(59,130,246,0.1)", border: "1px solid rgba(59,130,246,0.2)" }}>
                          <Building2 className="w-3.5 h-3.5" style={{ color: "rgba(147,197,253,0.8)" }} />
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="text-[12px] font-extrabold text-white">{s.companyName}</span>
                            {s.badge && <TrustBadgeChip badge={s.badge} />}
                          </div>
                          <p className="text-[10px] mt-0.5" style={{ color: "rgba(255,255,255,0.35)" }}>
                            {pName(s.province)} · {s.category}
                          </p>
                        </div>
                        <motion.button
                          whileTap={{ scale: 0.95 }}
                          onClick={() => setBadgeTarget(s)}
                          className="shrink-0 text-[9px] font-bold px-2 py-1 rounded-lg"
                          style={{ background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.1)", color: "rgba(255,255,255,0.4)" }}>
                          {t("admin.changeBadge")}
                        </motion.button>
                      </motion.div>
                    ))
                  )}
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* ── Badge Modal ────────────────────────────────────────────── */}
      <AnimatePresence>
        {badgeTarget && (
          <BadgeModal
            supplier={badgeTarget}
            onClose={() => setBadgeTarget(null)}
            onAssign={handleAssignBadge}
          />
        )}
      </AnimatePresence>

      {/* ── Toast ──────────────────────────────────────────────────── */}
      <AnimatePresence>
        {toast && (
          <motion.div
            initial={{ opacity: 0, y: 20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 10, scale: 0.95 }}
            className="fixed bottom-6 inset-x-0 flex justify-center z-50 pointer-events-none"
          >
            <div className="px-5 py-3 rounded-2xl flex items-center gap-2.5 text-[12px] font-bold"
              style={
                toast.type === "success"
                  ? { background: "rgba(16,185,129,0.18)", border: "1px solid rgba(16,185,129,0.5)", color: "rgba(110,231,183,1)", boxShadow: "0 0 24px rgba(16,185,129,0.2)" }
                  : { background: "rgba(239,68,68,0.15)", border: "1px solid rgba(239,68,68,0.4)", color: "rgba(252,165,165,1)", boxShadow: "0 0 20px rgba(239,68,68,0.15)" }
              }>
              {toast.type === "success" ? <CheckCircle2 className="w-4 h-4" /> : <AlertTriangle className="w-4 h-4" />}
              {toast.msg}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

